package com.kynsoft.report.infrastructure.entity;
import com.kynsoft.report.domain.dto.*; import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.LocalDateTime; import java.util.UUID;
@Getter @Setter @Entity @Table(name="documento_caja") public class DocumentoCaja { @Id private UUID id; @Column(nullable=false,unique=true) private Long numero; @Column(name="numero_documento",length=80) private String numeroDocumento; @Column(name="finca_id",nullable=false) private UUID fincaId; @Enumerated(EnumType.STRING) @Column(nullable=false) private TipoDocumentoCaja tipo; @Column(nullable=false) private LocalDateTime fecha; @Column(nullable=false) private Double importe; @Column(nullable=false) private String beneficiario; @Column(nullable=false) private String concepto; @Column(name="entregado_por") private String entregadoPor; @Column(name="recibido_por") private String recibidoPor; @Column(name="autorizado_por") private String autorizadoPor; private String referencia; private String observaciones; @Enumerated(EnumType.STRING) @Column(nullable=false) private EstadoDocumentoControl estado; @Column(name="usuario_id") private UUID usuarioId; }
